def min_longest_gap(relays, k):
    gaps = [b - a for a, b in zip(relays, relays[1:])]
    lo, hi = 1, max(gaps)
    while lo < hi:
        mid = (lo + hi) // 2
        # a gap g needs ceil(g / mid) - 1 new relays
        if sum((g - 1) // mid for g in gaps) <= k:
            hi = mid
        else:
            lo = mid + 1
    return lo

